/** Shared types and helpers for page sections (blocks). */
import type { AstroGlobal } from "astro";
import type { PageLayoutBlock } from "../../emdash-env";

/** Any section that can appear in a page's "Page sections" field. Types are generated by EmDash. */
export type Block = PageLayoutBlock;
export type BlockType = Block["_type"];
export type BlockOf<T extends BlockType> = Extract<Block, { _type: T }>;

/** Props every section component receives from EmDash's <Blocks>. */
export interface BlockProps<T extends BlockType> {
	value: BlockOf<T>;
	index: number;
	blockKey: string;
}

/** Block types that can carry the page's single H1. */
export const H1_BLOCKS: BlockType[] = ["hero", "profile", "page_header"];

/** Finds the first section of a given type. */
export function findBlock<T extends BlockType>(blocks: Block[], type: T): BlockOf<T> | undefined {
	return blocks.find((block): block is BlockOf<T> => block._type === type);
}

/** "h1" for the block chosen to carry the page's H1, otherwise "h2". */
export function headingTag(Astro: AstroGlobal, blockKey: string): "h1" | "h2" {
	return (Astro.locals as { h1Key?: string }).h1Key === blockKey ? "h1" : "h2";
}

export const str = (value: unknown): string => (typeof value === "string" ? value.trim() : "");
